begin;
select plan(18);
insert into auth.users(id,is_anonymous) values('f7000000-0000-4000-8000-000000000001',true),('f7000000-0000-4000-8000-000000000002',true);
select ok(not has_function_privilege('anon','public.change_band_availability(date[],date[])','execute'),'anonymous role cannot change dates');
set local role authenticated;
select set_config('request.jwt.claim.sub','f7000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"is_anonymous":true}',true);
select public.create_code_band('Atomic dates','Leader','기타','1234','112233');
select set_config('qa.atomic.band',public.current_band_identity()->>'band_id',true);
select set_config('qa.atomic.member',public.current_band_identity()->'member'->>'id',true);
select set_config('qa.atomic.code',public.band_login_settings()->>'code',true);
select set_config('qa.atomic.day',(now() at time zone 'Asia/Seoul')::date::text,true);
select lives_ok($$select public.change_band_availability(array[current_setting('qa.atomic.day')::date,current_setting('qa.atomic.day')::date+1],'{}')$$,'initial additions work');
select set_config('request.jwt.claim.sub','f7000000-0000-4000-8000-000000000002',true);
select public.begin_band_access(current_setting('qa.atomic.code'),'1234');select public.register_band_profile('Member','베이스','246810');
select public.change_band_availability(array[current_setting('qa.atomic.day')::date],'{}');
select set_config('request.jwt.claim.sub','f7000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.change_band_availability(array[current_setting('qa.atomic.day')::date+2],array[current_setting('qa.atomic.day')::date])$$,'combined change succeeds');
select ok(exists(select 1 from public.available_dates where member_id=current_setting('qa.atomic.member')::uuid and available_date=current_setting('qa.atomic.day')::date+2),'selected date added');
select ok(not exists(select 1 from public.available_dates where member_id=current_setting('qa.atomic.member')::uuid and available_date=current_setting('qa.atomic.day')::date),'selected date removed');
select ok(exists(select 1 from public.available_dates where member_id=current_setting('qa.atomic.member')::uuid and available_date=current_setting('qa.atomic.day')::date+1),'untouched own date preserved');
select ok(exists(select 1 from public.available_dates where member_id<>current_setting('qa.atomic.member')::uuid and band_id=current_setting('qa.atomic.band')::uuid and available_date=current_setting('qa.atomic.day')::date),'other member date preserved');
select throws_ok($$select public.change_band_availability(null,'{}')$$,'P0001','INVALID_INPUT','null list rejected');
select throws_ok($$select public.change_band_availability(array[null]::date[],'{}')$$,'P0001','INVALID_INPUT','null date rejected');
select throws_ok($$select public.change_band_availability(array[current_setting('qa.atomic.day')::date],array[current_setting('qa.atomic.day')::date])$$,'P0001','DUPLICATE_CONFLICT','overlap rejected');
select throws_ok($$select public.change_band_availability(array[current_setting('qa.atomic.day')::date,current_setting('qa.atomic.day')::date],'{}')$$,'P0001','DUPLICATE_CONFLICT','duplicate additions rejected');
select throws_ok($$select public.change_band_availability('{}',array[current_setting('qa.atomic.day')::date,current_setting('qa.atomic.day')::date])$$,'P0001','DUPLICATE_CONFLICT','duplicate removals rejected');
select throws_ok($$select public.change_band_availability(array[current_setting('qa.atomic.day')::date+367],array[current_setting('qa.atomic.day')::date+1])$$,'P0001','INVALID_INPUT','out of window addition rejected before removal');
reset role;
create function pg_temp.reject_date_delete() returns trigger language plpgsql as $$begin raise exception 'QA_DELETE_FAILURE';end$$;
create trigger qa_reject_date_delete before delete on public.available_dates for each row execute function pg_temp.reject_date_delete();
select set_config('qa.atomic.version',(select planning_version::text from public.bands where id=current_setting('qa.atomic.band')::uuid),true);
set local role authenticated;
select throws_ok($$select public.change_band_availability(array[current_setting('qa.atomic.day')::date+3],array[current_setting('qa.atomic.day')::date+1])$$,'P0001','QA_DELETE_FAILURE','failure after addition propagates');
select ok(not exists(select 1 from public.available_dates where member_id=current_setting('qa.atomic.member')::uuid and available_date=current_setting('qa.atomic.day')::date+3),'failed deletion rolls back preceding addition');
select ok(exists(select 1 from public.available_dates where member_id=current_setting('qa.atomic.member')::uuid and available_date=current_setting('qa.atomic.day')::date+1),'failed save keeps original date');
select is((select planning_version::text from public.bands where id=current_setting('qa.atomic.band')::uuid),current_setting('qa.atomic.version'),'failed save rolls back planning version too');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000000',true);
select throws_ok($$select public.change_band_availability('{}','{}')$$,'P0001','FORBIDDEN','unmapped session denied');
select * from finish();rollback;
